import com.project.system.service.WalletService;import java.math.BigDecimal;import java.util.*;import org.springframework.context.annotation.AnnotationConfigApplicationContext;
public class DebitIntegration{public static void main(String[]args){try(AnnotationConfigApplicationContext c=new AnnotationConfigApplicationContext(WalletIdentityIntegration.Config.class)){WalletService s=c.getBean(WalletService.class);BigDecimal before=(BigDecimal)s.info(2).get("balance");String key=UUID.randomUUID().toString();long id=s.trade(2,"PAY",new BigDecimal("1.25"),3L,null,key,1);if(s.trade(2,"PAY",new BigDecimal("1.25"),3L,null,key,1)!=id)throw new AssertionError();if(((BigDecimal)s.info(2).get("balance")).compareTo(before.subtract(new BigDecimal("1.25")))!=0)throw new AssertionError();System.out.println("PASS debit balance and duplicate request");try{s.trade(2,"PAY",new BigDecimal("100000"),3L,null,UUID.randomUUID().toString(),1);throw new AssertionError();}catch(IllegalArgumentException e){System.out.println("PASS insufficient balance rejected");}try{s.trade(2,"PAY",new BigDecimal("-1"),3L,null,UUID.randomUUID().toString(),1);throw new AssertionError();}catch(IllegalArgumentException e){System.out.println("PASS negative amount rejected");}System.out.println("PASS TOTAL 3");}}}
